public class MainActivity extends Activity {
 final int BG=Color.rgb(245,247,243),INK=Color.rgb(28,52,46),TEAL=Color.rgb(20,125,112),MUTED=Color.rgb(108,124,116),WARN=Color.rgb(162,86,25);
 Store store;LinearLayout root,body;int tab=0;boolean loaded=false;Handler handler=new Handler(Looper.getMainLooper());List<TextView> timers=new ArrayList<>();
 final Runnable tick=new Runnable(){public void run(){try{store=AppState.get(MainActivity.this);long now=Instant.now().getEpochSecond();if(AppState.tick(MainActivity.this))save();for(TextView t:timers)t.setText(careText((JSONObject)t.getTag(),now));if(!store.day().equals(store.data.optString("plan_day"))){store.generate();save();render();}}catch(Exception e){fail(e);}handler.postDelayed(this,1000);}};
 void fail(Exception e){new AlertDialog.Builder(this).setTitle("操作未完成").setMessage(e.getMessage()).setPositiveButton("知道了",null).show();}
 @Override public void onCreate(Bundle b){super.onCreate(b);try{store=AppState.get(this);if(!store.day().equals(store.data.optString("plan_day")))store.generate();AppState.tick(this);save();loaded=true;render();CareService.channels(this);}catch(Exception e){new AlertDialog.Builder(this).setTitle("无法读取本地数据").setMessage("原始数据未清除。\n"+e.getMessage()).setPositiveButton("关闭",(d,w)->finish()).show();}}
 @Override public void onResume(){super.onResume();if(loaded){try{store=AppState.get(this);AppState.tick(this);save();render();if(store.hasCare())startCare();}catch(Exception e){fail(e);}handler.removeCallbacks(tick);handler.post(tick);}}
 @Override public void onPause(){handler.removeCallbacks(tick);super.onPause();}
 void save(){AppState.use(this,store);}
 void startCare(){try{startForegroundService(new Intent(this,CareService.class));}catch(Exception e){Toast.makeText(this,"后台护理服务未启动，请保持此页打开查看计时",Toast.LENGTH_LONG).show();}}
 int dp(int x){return Math.round(x*getResources().getDisplayMetrics().density);}TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setPadding(0,dp(3),0,dp(3));return t;}TextView title(String s,int size){TextView t=text(s,size,INK);t.setTypeface(null,Typeface.BOLD);return t;}
 GradientDrawable bg(int c,int r){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(r));return d;}LinearLayout col(){LinearLayout v=new LinearLayout(this);v.setOrientation(1);return v;}LinearLayout row(){LinearLayout v=new LinearLayout(this);v.setOrientation(0);v.setGravity(Gravity.CENTER_VERTICAL);return v;}void gap(LinearLayout p,int h){p.addView(new View(this),new LinearLayout.LayoutParams(1,dp(h)));}
 LinearLayout card(){LinearLayout c=col();c.setPadding(dp(18),dp(14),dp(18),dp(14));c.setBackground(bg(Color.WHITE,20));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(12);body.addView(c,lp);return c;}
 Button button(String label,boolean primary,Runnable run){Button b=new Button(this);b.setAllCaps(false);b.setText(label);b.setTextSize(14);b.setTextColor(primary?Color.WHITE:TEAL);b.setBackground(bg(primary?TEAL:Color.rgb(231,242,236),14));b.setPadding(dp(12),dp(6),dp(12),dp(6));b.setMinHeight(dp(44));b.setMinimumHeight(dp(44));b.setOnClickListener(v->run.run());return b;}
 String clock(int m){return String.format(Locale.ROOT,"%02d:%02d",m/60,m%60);}String when(String s){if(s==null||s.equals("null")||s.isEmpty())return "待处理 · 未安排";LocalDateTime t=LocalDateTime.parse(s);return t.format(DateTimeFormatter.ofPattern("HH:mm"))+(t.toLocalDate().isAfter(LocalDate.parse(store.day()))?" · 次日":"");}
 String display(long seconds){return when(Constraints.local(seconds));}
 void render(){timers.clear();root=col();root.setBackgroundColor(BG);root.setPadding(dp(20),dp(16),dp(20),dp(12));setContentView(root);root.setOnApplyWindowInsetsListener((v,i)->{root.setPadding(dp(20),dp(16)+i.getSystemWindowInsetTop(),dp(20),dp(12)+i.getSystemWindowInsetBottom());return i;});root.requestApplyInsets();LinearLayout brand=row();brand.addView(title("◉  滴答护眼",19),new LinearLayout.LayoutParams(0,-2,1));brand.addView(text("v0.2-A",12,MUTED));root.addView(brand);gap(root,16);ScrollView scroll=new ScrollView(this);body=col();scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));try{if(tab==0)today();if(tab==1)meds();if(tab==2)history();if(tab==3)settings();}catch(Exception e){fail(e);}LinearLayout nav=row();String[] labels={"时间轴","药物","记录","作息"};for(int i=0;i<4;i++){final int n=i;LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(46),1);lp.setMargins(dp(2),0,dp(2),0);nav.addView(button(labels[i],tab==i,()->{tab=n;render();}),lp);}root.addView(nav);}
 void heading(String a,String b){body.addView(title(a,27));body.addView(text(b,14,MUTED));gap(body,16);}
 String status(JSONObject p){String s=p.optString("status");if(s.equals("Missed"))return "已漏滴";if(s.equals("Delayed"))return "延迟完成";if(p.optBoolean("done"))return "✓ 已完成";if(s.equals("Unresolved"))return "约束冲突";if(s.equals("NeedsReview"))return "过期待处理";return !p.isNull("scheduled")&&Constraints.epoch(p.optString("scheduled"))<Instant.now().getEpochSecond()?"过期待记录":"待完成";}
 String careText(JSONObject c,long now){now=AppState.careNow(this,c);long left=c.optString("status").equals("Completed")?0:Math.max(0,c.optLong("end_time")-now);if(left==0)return c.optString("name")+" · 护理计时已完成";boolean press=now<c.optLong("press_end");long phaseLeft=(press?c.optLong("press_end"):c.optLong("end_time"))-now;return c.optString("name")+"\n"+(press?"按压泪囊区，同时闭眼休息":"按压阶段已结束，继续闭眼休息")+"\n本阶段剩余 "+phaseLeft/60+":"+String.format(Locale.ROOT,"%02d",phaseLeft%60)+" · 总剩余 "+left/60+":"+String.format(Locale.ROOT,"%02d",left%60)+"\n护理期间不安排其他滴眼任务";}
 void today()throws Exception{
  heading("今日时间轴",LocalDate.parse(store.day()).format(DateTimeFormatter.ofPattern("M月d日 · EEEE",Locale.CHINA))+"  ·  "+clock(store.wake())+"—"+clock(store.end()));
  for(int i=0;i<store.cares().length();i++){JSONObject c=store.cares().getJSONObject(i);if(c.optString("status").equals("Completed"))continue;LinearLayout box=card();box.setBackground(bg(Color.rgb(222,240,221),20));box.addView(title("护理进行中",19));TextView timer=text(careText(c,Instant.now().getEpochSecond()),16,TEAL);timer.setTag(c);timers.add(timer);box.addView(timer);}
  int done=0;for(int i=0;i<store.plans().length();i++)if(store.plans().getJSONObject(i).optBoolean("done")&&!store.plans().getJSONObject(i).optString("status").equals("Missed"))done++;
  LinearLayout sum=card();sum.addView(title(done+" / "+store.plans().length()+"  已用药",25));sum.addView(text("计划与实际分开保存 · 未解决任务不强行排程",13,MUTED));sum.addView(button("预览重新安排",false,()->repair()));
  if(store.plans().length()==0){LinearLayout c=card();c.addView(title("先配置你的药物与规则",19));c.addView(button("＋ 添加药物",true,()->edit(null)));}
  ArrayList<JSONObject> tasks=new ArrayList<>();for(int i=0;i<store.plans().length();i++)tasks.add(store.plans().getJSONObject(i));tasks.sort(Comparator.comparing(p->p.optString("scheduled","9999")));
  for(JSONObject p:tasks){LinearLayout c=card();c.addView(title("●  "+when(p.optString("scheduled"))+"  ·  "+status(p),18));c.addView(title(p.optString("name"),20));c.addView(text("第 "+p.optInt("index")+" / "+p.optInt("total")+" 次"+(p.optString("dose").isEmpty()?"":" · "+p.optString("dose")),13,MUTED));
   if(!p.optString("original_scheduled").equals(p.optString("scheduled")))c.addView(text("原计划 "+when(p.optString("original_scheduled")),12,MUTED));
   if(p.optString("profile").equals("CYCLO")&&!p.isNull("scheduled")){long at=p.optBoolean("done")&&p.has("actual_epoch")?p.getLong("actual_epoch"):Constraints.at(p);c.addView(text("▧ 人工泪液保护区 "+display(at-900)+"—"+display(at+900)+"（两端可用）\n相邻环孢素间隔12小时",13,TEAL));}
   if(Constraints.care(p)>0&&!p.isNull("scheduled")){long at=p.optBoolean("done")&&p.has("actual_epoch")?p.getLong("actual_epoch"):Constraints.at(p);c.addView(text("▧ "+(p.optBoolean("done")?"实际":"计划")+"护理窗口 "+display(at)+"—"+display(at+Constraints.care(p))+" · 前"+p.optInt("press_seconds")/60+"分钟按压",13,TEAL));}
   if(p.has("conflict"))c.addView(text(p.optString("conflict"),13,WARN));
   if(p.optBoolean("done")){if(p.has("actual")&&!p.isNull("actual"))c.addView(text("实际 "+when(p.optString("actual")),14,TEAL));}
   else{gap(c,8);c.addView(button("记录已实际使用",true,()->confirmComplete(p)));gap(c,6);LinearLayout r=row();r.addView(button("调整时间",false,()->move(p)),new LinearLayout.LayoutParams(0,-2,1));r.addView(button("标记漏滴",false,()->missed(p)),new LinearLayout.LayoutParams(0,-2,1));c.addView(r);}
  }
  body.addView(text("过期不自动补滴。固定时间与间隔以已确认医嘱为准。",12,MUTED));gap(body,12);
 }
 void preview(Store candidate,String label)throws JSONException{
  final String baseline=store.records().toString();final String planDay=candidate.data.optString("plan_day");
  StringBuilder message=new StringBuilder();JSONArray conflicts=candidate.data.optJSONArray("conflicts");if(conflicts!=null&&conflicts.length()>0){message.append("以下任务暂不安排：\n");for(int i=0;i<conflicts.length();i++)message.append("• ").append(conflicts.getString(i)).append('\n');message.append('\n');}
  ArrayList<JSONObject> sorted=new ArrayList<>();for(int i=0;i<candidate.plans().length();i++)sorted.add(candidate.plans().getJSONObject(i));sorted.sort(Comparator.comparing(p->p.optString("scheduled","9999")));
  for(JSONObject p:sorted){if(p.optBoolean("done"))continue;message.append(p.optString("name")).append(" #").append(p.optInt("index")).append("  ").append(when(p.optString("scheduled")));JSONObject old=find(store.plans(),p.optString("id"));if(old!=null&&!old.optString("scheduled").equals(p.optString("scheduled")))message.append("（原 ").append(when(old.optString("scheduled"))).append('）');message.append('\n');}
  if(message.length()==0)message.append("没有待执行任务。已完成记录保持不变。");TextView contents=text(message.toString(),15,INK);contents.setPadding(dp(24),dp(12),dp(24),dp(12));ScrollView scroll=new ScrollView(this);scroll.addView(contents);
  new AlertDialog.Builder(this).setTitle(label).setView(scroll).setNegativeButton("取消",null).setPositiveButton("确认生效",(d,w)->{try{Store live=AppState.get(this);if(!baseline.equals(live.records().toString())||!planDay.equals(live.day()))throw new IllegalStateException("预览期间记录或日期已变化，请重新预览");candidate.data.put("cares",new JSONArray(live.cares().toString()));JSONArray errors=candidate.validation();if(errors.length()>0)throw new IllegalStateException("计划未通过约束复核：\n"+errors.toString());store=candidate;save();render();}catch(Exception e){fail(e);}}).show();
 }
 JSONObject find(JSONArray a,String id)throws JSONException{for(int i=0;i<a.length();i++)if(a.getJSONObject(i).optString("id").equals(id))return a.getJSONObject(i);return null;}
 void repair(){try{Store draft=store.copy();draft.generate(true,Instant.now().getEpochSecond());preview(draft,"调整后计划 · 确认才生效");}catch(Exception e){fail(e);}}
 void confirmComplete(JSONObject p){try{JSONArray errors=store.actualConflicts(p,Instant.now().getEpochSecond());String msg=p.optString("name")+"\n仅在已实际使用后确认，将以当前时间如实记录。";if(errors.length()>0)msg+="\n发现约束冲突（不是现在滴药的建议）：\n"+errors.toString();new AlertDialog.Builder(this).setTitle("记录已实际发生的用药").setMessage(msg).setNegativeButton("取消",null).setPositiveButton("确认已用药",(d,w)->{try{store.completeAt(p.getString("id"),Instant.now().getEpochSecond());for(int i=0;i<store.cares().length();i++){JSONObject c=store.cares().getJSONObject(i);if(c.optString("id").equals(p.getString("id"))&&!c.has("elapsed_start"))AppState.stamp(this,c);}save();if(store.hasCare()){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},9);startCare();}render();repair();}catch(Exception e){fail(e);}}).show();}catch(Exception e){fail(e);}}
 void missed(JSONObject p){new AlertDialog.Builder(this).setTitle("标记本次漏滴？").setMessage("只记录漏滴，不增加次数、不生成补滴任务。").setNegativeButton("取消",null).setPositiveButton("确认漏滴",(d,w)->{try{store.missed(p.getString("id"));save();render();repair();}catch(Exception e){fail(e);}}).show();}
 void move(JSONObject p){int base=store.wake();if(!p.isNull("scheduled")){LocalTime t=LocalDateTime.parse(p.optString("scheduled")).toLocalTime();base=t.getHour()*60+t.getMinute();}new TimePickerDialog(this,(v,h,m)->{try{Store draft=store.copy();JSONObject target=find(draft.plans(),p.getString("id"));long at=LocalDate.parse(draft.day()).atStartOfDay().plusMinutes(h*60+m).atZone(ZoneId.systemDefault()).toEpochSecond();if(at<draft.start())at+=86400;if(at<Instant.now().getEpochSecond())throw new IllegalArgumentException("该时间已过去，请补记实际使用或标记漏滴，不重新安排过期提醒");target.put("scheduled",Constraints.local(at)).put("scheduled_epoch",at).put("status","Pending");JSONArray errors=draft.validation();if(errors.length()>0){new AlertDialog.Builder(this).setTitle("时间与约束冲突").setMessage(errors.toString()).setNegativeButton("取消",null).setPositiveButton("重新安排预览",(d,w)->repair()).show();return;}draft.data.put("conflicts",new JSONArray());preview(draft,"手动调整 · 约束已检查");}catch(Exception e){fail(e);}},base/60,base%60,true).show();}
 void meds()throws Exception{heading("药物与时间规则","规则按配置启用，不根据药名自动推断");body.addView(button("＋ 添加药物",true,()->edit(null)));gap(body,14);for(int i=0;i<store.drugs().length();i++){JSONObject d=store.drugs().getJSONObject(i);LinearLayout c=card();c.addView(title(d.optString("name"),20));c.addView(text("每日 "+d.optInt("count")+" 次 · "+(d.optBoolean("active",true)?"启用":"暂停"),14,TEAL));c.addView(text(rules(d),14,MUTED));if(!d.optString("dose").isEmpty())c.addView(text("剂量："+d.optString("dose"),13,MUTED));if(!d.optString("note").isEmpty())c.addView(text(d.optString("note"),13,MUTED));gap(c,8);c.addView(button("编辑规则",false,()->edit(d)));}}
 String rules(JSONObject d){String p=d.optString("profile","GENERAL");if(p.equals("CYCLO"))return "FIXED_INTERVAL · 每12小时\nSEPARATION · 与人工泪液前后≥15分钟";if(p.equals("CARE"))return "POST_DOSE_CARE · 10分钟闭眼，前3分钟按压\nEXCLUSIVE_WINDOW · 护理期无其他滴眼任务";if(p.equals("TEARS"))return "SEPARATION · 与环孢素前后≥15分钟\n频次由医嘱确认，5–6次仅为说明书参考";return d.optInt("care_seconds")>0?"自定义护理 "+d.optInt("care_seconds")/60+"分钟，按压 "+d.optInt("press_seconds")/60+"分钟":"在清醒窗口均匀安排";}
 EditText field(LinearLayout p,String label,String val,int type){p.addView(text(label,14,MUTED));EditText e=new EditText(this);e.setText(val);e.setTextSize(16);e.setInputType(type);p.addView(e,new LinearLayout.LayoutParams(-1,-2));gap(p,8);return e;}
 void edit(JSONObject old){LinearLayout f=col();f.setPadding(dp(24),dp(8),dp(24),dp(8));EditText name=field(f,"药物名称 *",old==null?"":old.optString("name"),InputType.TYPE_CLASS_TEXT);f.addView(text("选择已确认的规则模板",14,MUTED));Spinner profile=new Spinner(this);String[] ids={"GENERAL","CYCLO","CARE","TEARS"};String[] labels={"普通药物 / 自定义护理","环孢素（兹润）· 2次 / 12小时","施图伦 · 3次 / 护理10分钟","人工泪液（珍视润）· 与环孢素隔15分钟"};profile.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,labels));int choice=0;if(old!=null)for(int i=0;i<ids.length;i++)if(ids[i].equals(old.optString("profile")))choice=i;profile.setSelection(choice);f.addView(profile);
  EditText count=field(f,"每日次数 *（按医嘱确认）",old==null?"1":old.optString("count"),InputType.TYPE_CLASS_NUMBER);EditText first=field(f,"环孢素首剂偏好时间（HH:mm）",clock(old==null?store.wake():old.optInt("first_time",store.wake())),InputType.TYPE_CLASS_DATETIME);EditText care=field(f,"自定义护理总分钟（普通药物，0为无）",old==null?"0":""+old.optInt("care_seconds")/60,InputType.TYPE_CLASS_NUMBER);EditText press=field(f,"其中按压分钟",old==null?"0":""+old.optInt("press_seconds")/60,InputType.TYPE_CLASS_NUMBER);EditText dose=field(f,"每次剂量（选填）",old==null?"":old.optString("dose"),InputType.TYPE_CLASS_TEXT);EditText note=field(f,"备注",old==null?"":old.optString("note"),InputType.TYPE_CLASS_TEXT);Switch active=new Switch(this);active.setText("启用");active.setChecked(old==null||old.optBoolean("active",true));f.addView(active);
  profile.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){boolean initial=true;public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int pos,long id){boolean fixed=pos==1||pos==2;if(!initial||old==null){if(pos==1)count.setText("2");if(pos==2)count.setText("3");}initial=false;count.setEnabled(!fixed);first.setEnabled(pos==1);care.setEnabled(pos==0);press.setEnabled(pos==0);}});
  ScrollView scroll=new ScrollView(this);scroll.addView(f);AlertDialog.Builder builder=new AlertDialog.Builder(this).setTitle(old==null?"添加药物":"编辑规则").setView(scroll).setNegativeButton("取消",null).setPositiveButton("预览计划",null);if(old!=null)builder.setNeutralButton("删除",(d,w)->remove(old));AlertDialog dialog=builder.create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(b->{try{String n=name.getText().toString().trim();if(n.isEmpty()){name.setError("请填写名称");return;}int c=Integer.parseInt(count.getText().toString());if(c<=0||c>1440)throw new IllegalArgumentException("每日次数须为1–1440的正整数");int selected=profile.getSelectedItemPosition();int cm=selected==0?Integer.parseInt(care.getText().toString()):0,pm=selected==0?Integer.parseInt(press.getText().toString()):0;LocalTime preferred=selected==1?LocalTime.parse(first.getText().toString()):LocalTime.of(store.wake()/60,store.wake()%60);JSONObject d=new JSONObject().put("id",old==null?UUID.randomUUID().toString():old.optString("id")).put("name",n).put("count",c).put("first_time",preferred.getHour()*60+preferred.getMinute()).put("dose",dose.getText().toString()).put("note",note.getText().toString()).put("active",active.isChecked());Store.configure(d,ids[selected],cm,pm);Store draft=store.copy();if(old==null)draft.drugs().put(d);else for(int i=0;i<draft.drugs().length();i++)if(draft.drugs().getJSONObject(i).optString("id").equals(old.optString("id")))draft.drugs().put(i,d);draft.generate(false,Instant.now().getEpochSecond());dialog.dismiss();preview(draft,"药物配置与计划预览");}catch(Exception e){fail(e);}}));dialog.show();
 }
 void remove(JSONObject d){new AlertDialog.Builder(this).setTitle("删除药物配置？").setMessage("已完成记录与正在进行的护理会保留。").setNegativeButton("取消",null).setPositiveButton("预览删除后计划",(x,w)->{try{Store draft=store.copy();for(int i=0;i<draft.drugs().length();i++)if(draft.drugs().getJSONObject(i).optString("id").equals(d.optString("id"))){draft.drugs().remove(i);break;}draft.generate();preview(draft,"删除后计划");}catch(Exception e){fail(e);}}).show();}
 void history()throws Exception{heading("记录与护理","原计划、调整后计划、实际时间独立保存");if(store.records().length()==0)card().addView(text("尚无实际记录。",16,MUTED));for(int i=store.records().length()-1;i>=0;i--){JSONObject r=store.records().getJSONObject(i);LinearLayout c=card();c.addView(title(r.optString("name"),20));c.addView(text(status(r),14,TEAL));c.addView(text("原计划 "+r.optString("original_scheduled").replace('T',' ')+"\n调整后 "+r.optString("scheduled").replace('T',' '),13,MUTED));if(!r.isNull("actual"))c.addView(text("实际 "+r.optString("actual").replace('T',' '),14,INK));JSONArray errors=r.optJSONArray("violations");if(errors!=null&&errors.length()>0)c.addView(text("实际用药冲突记录："+errors.toString(),13,WARN));for(int j=0;j<store.cares().length();j++){JSONObject care=store.cares().getJSONObject(j);if(!care.optString("id").equals(r.optString("id")))continue;c.addView(text("护理 "+display(care.getLong("start_time"))+"—"+display(care.getLong("end_time"))+" · "+(care.optString("status").equals("Completed")?"计时完成":"进行中"),14,TEAL));JSONArray acts=care.getJSONArray("actions");for(int k=0;k<acts.length();k++){JSONObject a=acts.getJSONObject(k);c.addView(text((a.optString("action_type").equals("PRESS_LACRIMAL")?"按压泪囊区":"闭眼休息")+" · "+a.optInt("duration")/60+"分钟 · "+a.optString("status"),12,MUTED));}}}}
 void settings(){heading("作息与权限","调整前会重新检查硬约束");LinearLayout c=card();c.addView(button("起床时间 "+clock(store.wake()),false,()->pick(true)));gap(c,10);c.addView(button("结束时间 "+clock(store.end())+(store.end()<store.wake()?" 次日":""),false,()->pick(false)));gap(c,12);c.addView(text("12小时间隔或护理窗口无法放入清醒窗口时，任务会显示待处理；不会压缩间隔。",14,MUTED));LinearLayout about=card();about.addView(title("护理阶段通知",19));about.addView(text("后台护理使用前台计时服务。请允许通知并保留系统中的护理通知。被强行停止或重启后，打开应用会根据时间戳恢复计时；系统限制可能影响后台提示。",14,MUTED));about.addView(button("允许护理通知",false,()->{if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},9);else startActivity(new Intent("android.settings.APP_NOTIFICATION_SETTINGS").putExtra("android.provider.extra.APP_PACKAGE",getPackageName()));}));LinearLayout privacy=card();privacy.addView(text("本地保存，无账号、无网络权限。升级保留v0.1记录；卸载或清除数据会删除记录。\nv0.2-A：用药约束、护理计时、冲突预览。每日滴药闹钟、自动重启通知恢复尚未提供。",13,MUTED));}
 void pick(boolean wake){int current=wake?store.wake():store.end();new TimePickerDialog(this,(v,h,m)->{try{Store draft=store.copy();int start=wake?h*60+m:store.wake(),end=wake?store.end():h*60+m;Schedule.window(start,end);draft.data.put("wake",start).put("end",end);draft.generate();preview(draft,"作息变更与排程预览");}catch(Exception e){fail(e);}},current/60,current%60,true).show();}
}
